package com.tencent.weknora.knowledge;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.io.*;
import java.util.*;
import java.util.regex.*;

/** Production Go structured graph prompt and formatter, including malformed-fence recovery. */
public final class GraphExtractionText {
  public record Node(String name,List<String> attributes,List<String> chunks) {}
  public record Relation(String source,String target,String type) {}
  public record Graph(List<Node> nodes,List<Relation> relations) {}
  private final ObjectMapper json;private final String description;
  private static final Pattern FENCE=Pattern.compile("```([A-Za-z0-9_+\\-]+)?(?:\\s*\\n)?([\\s\\S]*?)```");
  public GraphExtractionText(ObjectMapper json){this(json,null);}
  public GraphExtractionText(ObjectMapper json,String description){this.json=json;if(description!=null)this.description=description;else try(var in=getClass().getResourceAsStream("/graph-extraction-prompt.json")){this.description=json.readTree(Objects.requireNonNull(in)).path("description").asText();}catch(IOException e){throw new UncheckedIOException(e);}}
  public List<ObjectNode> messages(String content,JsonNode config){
    JsonNode tags=config.path("tags");String d=description,instructions=SummaryGenerationText.trim(config.path("custom_instructions").asText());if(tags.isArray()&&!tags.isEmpty())instructions=instructions.replace("%","%%");if(!instructions.isEmpty())d=SummaryGenerationText.trim(d)+"\n\n<graph_extraction_business_instructions>\n"+instructions+"\n</graph_extraction_business_instructions>\nApply these business instructions only when they do not conflict with the system-owned output format, citation, safety, or factuality rules.";
    if(tags.isArray()&&!tags.isEmpty())d=formatDescription(d,compact(tags));
    var examples=json.createArrayNode();for(var n:config.path("nodes")){var item=json.createObjectNode().put("entity",n.path("name").asText());if(n.path("attributes").isArray()&&!n.path("attributes").isEmpty())item.set("entity_attributes",n.get("attributes"));examples.add(item);}for(var r:config.path("relations"))examples.add(json.createObjectNode().put("entity1",r.path("node1").asText()).put("entity2",r.path("node2").asText()).put("relation",r.path("type").asText()));
    String system=d+"\n# Examples\nQ: "+SummaryGenerationText.trim(config.path("text").asText())+"\nA: ```json\n"+pretty(examples,0)+"\n```\n";
    return List.of(json.createObjectNode().put("role","system").put("content",system),json.createObjectNode().put("role","user").put("content","# Question\nQ: "+content+"\nA: "));
  }
  public ObjectNode options(){return json.createObjectNode().put("temperature",.3).put("max_tokens",8192).put("thinking",false);}
  public Graph parse(String text){try{
    String content=extract(text);if(content.isEmpty())throw new IllegalArgumentException("empty or invalid input string");JsonNode parsed=parseNumbersAsGoFloat64(content);if(parsed==null||parsed.isNull()||!parsed.isArray()&&!parsed.isObject())throw new IllegalArgumentException("content must be a list of extractions or a dict");List<JsonNode> groups=new ArrayList<>();if(parsed.isObject())groups.add(parsed);else parsed.forEach(groups::add);var nodes=new LinkedHashMap<String,Node>();var relations=new ArrayList<Relation>();
    for(var g:groups){if(!g.isObject())throw new IllegalArgumentException("each item in the sequence must be a mapping.");if(g.hasNonNull("entity")){var attrs=new ArrayList<String>();if(g.path("entity_attributes").isArray())g.path("entity_attributes").forEach(v->attrs.add(goValue(v)));String name=goValue(g.get("entity"));nodes.putIfAbsent(name,new Node(name,List.copyOf(attrs),List.of()));}else if(g.hasNonNull("entity1")&&g.hasNonNull("entity2")){relations.add(new Relation(goValue(g.get("entity1")),goValue(g.get("entity2")),goValue(g.get("relation"))));}}
    var valid=new ArrayList<Relation>();for(var r:relations){if(r.source().equals(r.target()))continue;nodes.putIfAbsent(r.source(),new Node(r.source(),List.of(),List.of()));nodes.putIfAbsent(r.target(),new Node(r.target(),List.of(),List.of()));valid.add(r);}return new Graph(List.copyOf(nodes.values()),List.copyOf(valid));
  }catch(IOException e){throw new IllegalArgumentException("failed to parse JSON content",e);}}
  static String extract(String text){if(text==null||text.isEmpty())return "";var m=FENCE.matcher(text);var matches=new ArrayList<String>();var candidates=new ArrayList<String>();while(m.find()){matches.add(m.group(2));String tag=m.group(1);if(tag==null||tag.isEmpty()||tag.equalsIgnoreCase("json"))candidates.add(m.group(2));}if(!candidates.isEmpty())return SummaryGenerationText.trim(candidates.getFirst());if(!matches.isEmpty())return SummaryGenerationText.trim(matches.getFirst());String s=SummaryGenerationText.trim(text);int fence=s.indexOf("```");if(fence>=0){String rest=s.substring(fence+3);int nl=rest.indexOf('\n');if(nl>=0){String first=SummaryGenerationText.trim(rest.substring(0,nl));if(first.isEmpty()||first.length()<=16&&first.matches("[A-Za-z0-9_+\\-]*"))rest=rest.substring(nl+1);}int end=rest.indexOf("```");if(end>=0)rest=rest.substring(0,end);rest=SummaryGenerationText.trim(rest).replaceAll("^`+|`+$","");if(!SummaryGenerationText.trim(rest).isEmpty())return SummaryGenerationText.trim(rest);}
    int object=s.indexOf('{'),array=s.indexOf('[');int start=object<0?array:array<0?object:Math.min(object,array);if(start>=0){char open=s.charAt(start),close=open=='{'?'}':']';int depth=0;boolean quote=false,escape=false;for(int i=start;i<s.length();i++){char c=s.charAt(i);if(quote){if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quote=false;continue;}if(c=='"'){quote=true;continue;}if(c==open)depth++;else if(c==close&&--depth==0)return s.substring(start,i+1);}}return s;
  }
  private String compact(JsonNode n){try{return json.writeValueAsString(n).replace("<","\\u003c").replace(">","\\u003e").replace("&","\\u0026").replace("\u2028","\\u2028").replace("\u2029","\\u2029");}catch(IOException e){throw new UncheckedIOException(e);}}
  private String pretty(JsonNode n,int depth){if(!n.isContainerNode()||n.isEmpty())return compact(n);String indent="  ".repeat(depth),inside=indent+"  ";var lines=new ArrayList<String>();if(n.isArray()){n.forEach(v->lines.add(inside+pretty(v,depth+1)));return "[\n"+String.join(",\n",lines)+"\n"+indent+"]";}var fields=new TreeMap<String,JsonNode>();n.fields().forEachRemaining(e->fields.put(e.getKey(),e.getValue()));fields.forEach((k,v)->lines.add(inside+compact(TextNode.valueOf(k))+": "+pretty(v,depth+1)));return "{\n"+String.join(",\n",lines)+"\n"+indent+"}";}
  private static String formatDescription(String d,String tags){var out=new StringBuilder();boolean used=false;for(int i=0;i<d.length();i++){char c=d.charAt(i);if(c=='%'&&i+1<d.length()){char next=d.charAt(++i);if(next=='%')out.append('%');else if(next=='s'&&!used){out.append(tags);used=true;}else out.append("%!").append(next).append("(MISSING)");}else out.append(c);}if(!used)out.append("%!(EXTRA string=").append(tags).append(')');return out.toString();}
  /** Go's encoding/json decodes every interface number as binary64, including negative zero. */
  JsonNode parseNumbersAsGoFloat64(String content)throws IOException {try(var p=json.getFactory().createParser(content)){if(p.nextToken()==null)return null;var value=readGoValue(p);if(p.nextToken()!=null)throw new IllegalArgumentException("trailing JSON content");return value;}}
  private JsonNode readGoValue(com.fasterxml.jackson.core.JsonParser p)throws IOException {return switch(p.currentToken()){
    case START_ARRAY -> {var a=json.createArrayNode();while(p.nextToken()!=com.fasterxml.jackson.core.JsonToken.END_ARRAY){if(p.currentToken()==null)throw new IllegalArgumentException("incomplete array");a.add(readGoValue(p));}yield a;}
    case START_OBJECT -> {var o=json.createObjectNode();while(p.nextToken()!=com.fasterxml.jackson.core.JsonToken.END_OBJECT){if(p.currentToken()!=com.fasterxml.jackson.core.JsonToken.FIELD_NAME)throw new IllegalArgumentException("invalid object");String key=p.currentName();if(p.nextToken()==null)throw new IllegalArgumentException("incomplete object");o.set(key,readGoValue(p));}yield o;}
    case VALUE_STRING -> TextNode.valueOf(p.getText());
    case VALUE_TRUE -> BooleanNode.TRUE;case VALUE_FALSE -> BooleanNode.FALSE;case VALUE_NULL -> NullNode.instance;
    case VALUE_NUMBER_INT,VALUE_NUMBER_FLOAT -> {double d=Double.parseDouble(p.getText());if(!Double.isFinite(d))throw new IllegalArgumentException("JSON number exceeds float64 range");yield DoubleNode.valueOf(d);}
    default -> throw new IllegalArgumentException("invalid JSON value");};}
  /** Equivalent to strconv.FormatFloat(f, 'g', -1, 64), using the shortest round-tripping decimal. */
  static String goFloat64(double d){if(!Double.isFinite(d))throw new IllegalArgumentException("nonfinite graph number");if(d==0)return Double.doubleToRawLongBits(d)<0?"-0":"0";var exact=new java.math.BigDecimal(d);java.math.BigDecimal shortest=null;for(int precision=1;precision<=17;precision++){var candidate=exact.round(new java.math.MathContext(precision,java.math.RoundingMode.HALF_EVEN));if(Double.doubleToRawLongBits(Double.parseDouble(candidate.toString()))==Double.doubleToRawLongBits(d)){shortest=candidate.stripTrailingZeros();break;}}if(shortest==null)throw new IllegalArgumentException("cannot format graph number");int exponent=shortest.precision()-shortest.scale()-1;if(exponent>=-4&&exponent<6)return shortest.toPlainString();String digits=shortest.unscaledValue().abs().toString();String mantissa=(d<0?"-":"")+digits.charAt(0)+(digits.length()>1?"."+digits.substring(1):"");String exp=Integer.toString(Math.abs(exponent));return mantissa+"e"+(exponent<0?"-":"+")+(exp.length()==1?"0":"")+exp;}
  static String goValue(JsonNode n){if(n==null||n.isNull())return "<nil>";if(n.isTextual())return n.textValue();if(n.isNumber())return goFloat64(n.doubleValue());if(n.isBoolean())return n.asText();if(n.isArray()){var values=new ArrayList<String>();n.forEach(v->values.add(goValue(v)));return "["+String.join(" ",values)+"]";}var values=new TreeMap<String,String>();n.fields().forEachRemaining(e->values.put(e.getKey(),goValue(e.getValue())));return "map["+String.join(" ",values.entrySet().stream().map(e->e.getKey()+":"+e.getValue()).toList())+"]";}
}
